      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Volume vs. precision</text>\n                    <rect x=\"60\" y=\"200\" width=\"480\" height=\"300\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"300\" y=\"260\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">50 POSTS</text>\n                    <text x=\"300\" y=\"315\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">High volume</text>\n                    <text x=\"300\" y=\"355\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Broad audience</text>\n                    <text x=\"300\" y=\"400\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Vanity metrics</text>\n                    <text x=\"300\" y=\"435\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Few buyers reached</text>\n                    <text x=\"300\" y=\"475\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">Low ROI</text>\n                    <rect x=\"560\" y=\"200\" width=\"480\" height=\"300\" rx=\"20\" fill=\"rgba(16,185,129,0.1)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"800\" y=\"260\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">12 × 25 NAMED</text>\n                    <text x=\"800\" y=\"315\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">300 ideal buyers</text>\n                    <text x=\"800\" y=\"355\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Personal delivery</text>\n                    <text x=\"800\" y=\"400\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Real conversations</text>\n                    <text x=\"800\" y=\"435\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Engagements close</text>\n                    <text x=\"800\" y=\"475\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">High ROI</text>\n                    <rect x=\"200\" y=\"560\" width=\"700\" height=\"180\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"615\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">Distribution to named buyers</text>\n                    <text x=\"550\" y=\"660\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">is the conversion event.</text>\n                    <text x=\"550\" y=\"710\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Production is a small fraction of the win.</text>\n                </svg>",
