      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Handling the price objection</text>\n                    <rect x=\"60\" y=\"200\" width=\"480\" height=\"280\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"300\" y=\"260\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">SPLIT DIFFERENCE</text>\n                    <text x=\"300\" y=\"315\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">\"I'll do $225K\"</text>\n                    <text x=\"300\" y=\"370\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Signals original was inflated</text>\n                    <text x=\"300\" y=\"410\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Every future fee negotiable</text>\n                    <text x=\"300\" y=\"450\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">Vendor capitulation</text>\n                    <rect x=\"560\" y=\"200\" width=\"480\" height=\"280\" rx=\"20\" fill=\"rgba(16,185,129,0.1)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"800\" y=\"260\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">REFRAME + RESCOPE</text>\n                    <text x=\"800\" y=\"315\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">\"7% of $3.5M value\"</text>\n                    <text x=\"800\" y=\"370\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Re-anchors on agreed value</text>\n                    <text x=\"800\" y=\"410\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Smaller scope, smaller fee</text>\n                    <text x=\"800\" y=\"450\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">Peer discipline</text>\n                    <rect x=\"200\" y=\"540\" width=\"700\" height=\"180\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"595\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">Discount the SCOPE,</text>\n                    <text x=\"550\" y=\"635\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">never the FEE.</text>\n                    <text x=\"550\" y=\"685\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Re-anchor on value before any price move.</text>\n                </svg>",
      "caption": "The right answer to 'too high'"
