      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">90 DAYS, $190K SIGNED</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Priya Krishnan — case in execution</text>\n                    <rect x=\"80\" y=\"180\" width=\"940\" height=\"120\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"225\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">WEEK 1 — POSITION</text>\n                    <text x=\"120\" y=\"265\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">\"CCO, Series B/C SaaS, cut churn 30-50%\"</text>\n                    <rect x=\"80\" y=\"320\" width=\"940\" height=\"120\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"365\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"22\">DAYS 8-30 — ENGINE</text>\n                    <text x=\"120\" y=\"405\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">4 articles, 100 notes, 20 referrals, 8 speeches</text>\n                    <rect x=\"80\" y=\"460\" width=\"940\" height=\"120\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"505\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">DAYS 31-60 — CONVERT</text>\n                    <text x=\"120\" y=\"545\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">17 discovery calls, 8 agreements, 5 proposals</text>\n                    <rect x=\"80\" y=\"600\" width=\"940\" height=\"160\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"120\" y=\"650\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"22\">DAYS 61-90 — CLOSE</text>\n                    <text x=\"120\" y=\"695\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">$65K Series C + $45K Series B + $80K growth SaaS</text>\n                    <text x=\"120\" y=\"730\" text-anchor=\"start\" fill=\"#888\" font-size=\"18\">First close day 58, then two more</text>\n                    <rect x=\"80\" y=\"780\" width=\"940\" height=\"160\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"835\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"28\">$190K SIGNED</text>\n                    <text x=\"550\" y=\"880\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Year 1 trajectory: $480K-$620K</text>\n                    <text x=\"550\" y=\"915\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">3 engagements + 6 active + 12 warm + speaking</text>\n                </svg>",
