      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE BEGINNER TRAP</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Premature retreat to safe activities</text>\n                    <rect x=\"80\" y=\"200\" width=\"940\" height=\"240\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"255\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">SAFE-FEELING ACTIVITIES</text>\n                    <text x=\"550\" y=\"305\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Endless website polish</text>\n                    <text x=\"550\" y=\"345\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Market research, more certifications</text>\n                    <text x=\"550\" y=\"385\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Networking events, \"validation interviews\"</text>\n                    <text x=\"550\" y=\"425\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Producing output without producing revenue</text>\n                    <rect x=\"80\" y=\"470\" width=\"940\" height=\"240\" rx=\"20\" fill=\"rgba(16,185,129,0.1)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"525\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">REVENUE-GENERATING (80% TIME)</text>\n                    <text x=\"550\" y=\"575\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Outreach to named buyers</text>\n                    <text x=\"550\" y=\"615\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Published articles + discovery calls</text>\n                    <text x=\"550\" y=\"655\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Proposals + follow-ups</text>\n                    <text x=\"550\" y=\"695\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Where clients actually come from</text>\n                    <rect x=\"200\" y=\"740\" width=\"700\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"800\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">\"You have an outreach problem.</text>\n                    <text x=\"550\" y=\"845\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">Every other diagnosis is wrong.\"</text>\n                    <text x=\"550\" y=\"900\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">— Weiss to first-90-day consultants</text>\n                </svg>",
      "caption": "Beware activities that feel like work"
