      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Day 45 diagnosis</text>\n                    <rect x=\"100\" y=\"200\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">SYMPTOMS</text>\n                    <text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Website polish, branding course, networking</text>\n                    <text x=\"550\" y=\"355\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">2 buyer conversations, 0 proposals</text>\n                    <rect x=\"100\" y=\"430\" width=\"900\" height=\"240\" rx=\"20\" fill=\"rgba(16,185,129,0.1)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"490\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">THE FIX</text>\n                    <text x=\"550\" y=\"540\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Stop infrastructure work today</text>\n                    <text x=\"550\" y=\"585\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Execute 5 weekly revenue actions</text>\n                    <text x=\"550\" y=\"630\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">25 notes / 5 referrals / 1 article / 2 speeches / engagement</text>\n                    <rect x=\"200\" y=\"710\" width=\"700\" height=\"180\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"770\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">The diagnosis is always</text>\n                    <text x=\"550\" y=\"815\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">insufficient outreach.</text>\n                    <text x=\"550\" y=\"865\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Lower fees ≠ solution. Coach ≠ solution. Do the work.</text>\n                </svg>",
